// ============================================================================
// src/lib/tools/bit-numbering-and-order/golden-vectors.ts
// ----------------------------------------------------------------------------
// GOLDEN VECTORS for the bit numbering and bit order tool.
//
// Every expected value in the two tables below was computed on 2026-11-08 by a
// separate Python model (work/oracle.py in the build folder), written from the
// documents and not from this engine: bits as Python's binary text, MSB 0
// positions as string indexes, LSB 0 as width - 1 - index (Intel SDM 1.3.1),
// 1-based as width - index (RFC 3417 s8), bit reversal by reversing the text,
// octets by int.to_bytes, the Ethernet order by reversing each octet's text
// (RFC 9542 s1.1), the MSB format by the same per-octet reversal (RFC 2469),
// the layouts from their documents' MSB 0 drawings, negative decimals by
// modular arithmetic. gen_vectors.py wrote this file from that output, so no
// computed number was typed by hand. CASE_TABLE pins whole readings (subsets:
// every field the oracle computes); OCTET_TABLE pins all 256 octets in value
// mode and, read least significant bit first, in printed mode. The refusals,
// the sentences and the API texts are written out after them, each with the
// rule it pins. The page's Examples and samples (examples.ts) must be
// vectors here: verifyVectors fails otherwise.
// GOLDEN_VECTOR_SET_ID changes whenever a vector changes (the api-sync rule).
// ============================================================================

import { run, runApi, type BitRequest, type BitResult } from "./compute"; // the engine's API entries
import { EXAMPLES, SAMPLES } from "./examples"; // the page's Examples and samples, pinned below

/** The set id: dated, changed with any vector (scripts/check-api-sync.mjs compares it with scripts/api-sync.json). */
export const GOLDEN_VECTOR_SET_ID = "bit-numbering-and-order-golden-2026-11-08"; // the first set

/** One vector: a request (or raw API text), and either the fields expected or the error expected. */
export interface BitVector {
  /** A stable id. */
  id: string;
  /** Where the expected values come from, or the rule pinned. */
  note: string;
  /** The request object (run()). */
  request?: BitRequest;
  /** Or the raw API body (runApi()). */
  api?: string;
  /** The fields expected (a subset of the reading; objects compared as subsets, arrays element by element). */
  expect?: Record<string, unknown>;
  /** Text the reading's notes must contain. */
  notes?: string[];
  /** The error expected, as a pattern over its message. */
  expectError?: RegExp;
}

